    os.makedirs(f"{H}/findings-all/{repo}", exist_ok=True)
    with open(f"{H}/findings-all/{repo}/{rname}-{n}.json", "w") as fh:
        json.dump(out_all, fh, indent=1)
    return item, {st: len(v.get("findings", [])) for st, v in out_all.items()}, any("error" in v for v in out_all.values())


